/**
 * Single entry point for writing rows into `chats`.
 *
 * Every message records WHO authored it in chats.metadata. Without this the
 * agent's own replies are indistinguishable from Rohan's real messages, so the
 * model ends up imitating its own past output and drifts further from his voice
 * with every turn.
 *
 *   metadata.source:
 *     'human'  - actually typed by Rohan (fromMe on his phone, or imported from
 *                a WhatsApp export). ONLY these are eligible as style exemplars.
 *     'ai'     - generated by this agent. Never used as a style exemplar.
 *     'mock'   - synthetic seed/demo data. Never used as a style exemplar.
 *
 * Rows written before provenance existed have metadata = NULL and are treated as
 * unknown, i.e. excluded from exemplars.
 */
const { supabase } = require('./supabaseClient');

const SOURCES = ['human', 'ai', 'mock'];

/**
 * @param {object}  opts
 * @param {number}  opts.contactId
 * @param {string}  opts.message
 * @param {'INCOMING'|'OUTGOING'} opts.direction
 * @param {'human'|'ai'|'mock'}   opts.source
 * @param {string} [opts.model]      model id, for source==='ai'
 * @param {object} [opts.extra]      extra keys merged into metadata
 * @param {string} [opts.createdAt]  ISO timestamp; omit to use the DB default
 */
function buildRow({ contactId, message, direction, source, model, extra, createdAt }) {
    if (!SOURCES.includes(source)) {
        throw new Error(`chatStore: unknown source "${source}" (expected ${SOURCES.join('|')})`);
    }
    const metadata = { source, ...(model ? { model } : {}), ...(extra || {}) };
    const row = { contact_id: contactId, message, direction, metadata };
    if (createdAt) row.created_at = createdAt;
    return row;
}

async function saveMessage(opts) {
    const { data, error } = await supabase.from('chats').insert(buildRow(opts)).select().single();
    if (error) throw error;
    return data;
}

async function saveMany(list) {
    const rows = list.map(buildRow);
    const { data, error } = await supabase.from('chats').insert(rows).select();
    if (error) throw error;
    return data;
}

/** True when a chat row was authored by a real human and is safe to imitate. */
function isHumanAuthored(row) {
    return !!row && !!row.metadata && row.metadata.source === 'human';
}

module.exports = { saveMessage, saveMany, buildRow, isHumanAuthored, SOURCES };
